import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config: NodeConfig, ctx: NodeContext): THREE.Object3D {
  const root = new THREE.Group();
  const materials: THREE.Material[] = [];
  const timelines: gsap.core.Timeline[] = [];

  // Dimensions
  const CARD_W = 1.5, CARD_H = 1.9, GAP = 0.25;
  const PADDING = 0.375;
  const ICON_D = 0.4, ICON_Z = 0.05;
  const BASELINE = 0.25;
  const COLS = 3;
  const ROW_W = COLS * CARD_W + (COLS - 1) * GAP;
  const START_X = -ROW_W / 2 + CARD_W / 2;

  const cardData = [
    { icon: '01', title: 'In-House Calibre', body: 'Every movement is designed, machined, and finished under one roof.' },
    { icon: '02', title: 'Five-Year Guarantee', body: 'Each piece is serviced free of charge for five years from delivery.' },
    { icon: '03', title: 'Hand-Finished Dials', body: 'Guilloche cut on a 1912 rose engine, one dial at a time.' },
  ];

  cardData.forEach((card, idx) => {
    const cardGroup = new THREE.Group();
    cardGroup.position.x = START_X + idx * (CARD_W + GAP);

    // Card background
    const cardMat = new THREE.MeshStandardMaterial({
      color: 0x121218,
      roughness: 0.6,
      metalness: 0.25,
      clearcoat: 0.15,
    });
    materials.push(cardMat);

    const cardGeo = new THREE.PlaneGeometry(CARD_W, CARD_H);
    const cardMesh = new THREE.Mesh(cardGeo, cardMat);
    cardGroup.add(cardMesh);

    // Icon seat disc
    const discMat = new THREE.MeshStandardMaterial({
      color: 0x1a1a20,
      emissive: 0xff2a38,
      emissiveIntensity: 1.6,
      roughness: 0.55,
      metalness: 0.5,
      clearcoat: 0.2,
    });
    materials.push(discMat);

    const discGeo = new THREE.CylinderGeometry(ICON_D / 2, ICON_D / 2, ICON_Z, 32);
    const discMesh = new THREE.Mesh(discGeo, discMat);
    const discY = CARD_H / 2 - PADDING - ICON_D / 2;
    discMesh.position.set(0, discY, ICON_Z / 2 + 0.001);
    cardGroup.add(discMesh);

    // Icon glyph text
    const glyphMesh = renderTextViaAtlas(ctx, card.icon, {
      size: 20,
      weight: 700,
      color: 0xff2a38,
      emissive: 0xff2a38,
      emissiveIntensity: 1.6,
    });
    if (glyphMesh) {
      glyphMesh.position.copy(discMesh.position);
      glyphMesh.position.z += 0.002;
      cardGroup.add(glyphMesh);
    }

    // Title text
    const titleMesh = renderTextViaAtlas(ctx, card.title, {
      size: 20,
      weight: 600,
      color: 0xe8ecf2,
      maxWidth: CARD_W - 2 * PADDING,
    });
    if (titleMesh) {
      titleMesh.position.set(0, discY - ICON_D / 2 - BASELINE, 0.001);
      cardGroup.add(titleMesh);
    }

    // Body text
    const bodyMesh = renderTextViaAtlas(ctx, card.body, {
      size: 13,
      weight: 400,
      color: 0x808088,
      maxWidth: CARD_W - 2 * PADDING,
    });
    if (bodyMesh) {
      const bodyY = (titleMesh?.position.y ?? 0) - BASELINE / 2;
      bodyMesh.position.set(0, bodyY, 0.001);
      cardGroup.add(bodyMesh);
    }

    // Hover handlers
    cardMesh.userData.handlers = {
      onPointerEnter: () => {
        const tl = gsap.timeline();
        tl.to(cardGroup.position, { y: 0.06, duration: 0.18, ease: 'power2.out' }, 0);
        tl.to(cardGroup.scale, { z: 1.04, duration: 0.18, ease: 'power2.out' }, 0);
        tl.to(discMat, { emissiveIntensity: 2.2, duration: 0.18, ease: 'power2.out' }, 0);
        timelines.push(tl);
      },
      onPointerLeave: () => {
        const tl = gsap.timeline();
        tl.to(cardGroup.position, { y: 0, duration: 0.18, ease: 'power2.out' }, 0);
        tl.to(cardGroup.scale, { z: 1, duration: 0.18, ease: 'power2.out' }, 0);
        tl.to(discMat, { emissiveIntensity: 1.6, duration: 0.18, ease: 'power2.out' }, 0);
        timelines.push(tl);
      },
    };

    root.add(cardGroup);
  });

  // Mount stagger animation
  const mountTl = gsap.timeline();
  const cardGroups = Array.from(root.children) as THREE.Group[];

  cardGroups.forEach((cardGroup, i) => {
    cardGroup.position.y = 0.2;
    cardGroup.traverse((obj) => {
      if (obj instanceof THREE.Mesh && obj.material instanceof THREE.Material) {
        (obj.material as any).transparent = true;
        (obj.material as any).opacity = 0;
      }
    });

    const delay = i * 0.08;
    mountTl.to(cardGroup.position, { y: 0, duration: 0.5, ease: 'power2.out' }, delay);

    cardGroup.traverse((obj) => {
      if (obj instanceof THREE.Mesh && obj.material instanceof THREE.Material) {
        mountTl.to(obj.material, { opacity: 1, duration: 0.5, ease: 'power2.out' }, delay);
      }
    });
  });

  timelines.push(mountTl);

  // Cleanup
  root.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    timelines.length = 0;
    materials.forEach((mat) => mat.dispose());
    materials.length = 0;
    root.traverse((obj) => {
      if (obj instanceof THREE.Mesh) {
        obj.geometry.dispose();
      }
    });
  };

  return root;
}

function renderTextViaAtlas(
  ctx: NodeContext,
  text: string,
  options: Record<string, any>
): THREE.Object3D | null {
  try {
    if (!ctx.fontAtlas) return null;
    const fa = ctx.fontAtlas as any;
    if (typeof fa.renderText === 'function') {
      return fa.renderText(text, options);
    }
    if (typeof fa === 'function') {
      return fa(text, options);
    }
  } catch (err) {
    console.warn(`fontAtlas render failed for "${text}":`, err);
  }
  return null;
}
